zig
const std = @import("std");
const http = std.http;
const json = std.json;
const net = std.net;
const crypto = std.crypto;
const Thread = std.Thread;
const Allocator = std.mem.Allocator;

const CerebrasClient = @import("cerebras_client.zig");
const DragonflyClient = @import("dragonfly_client.zig");
const ModalClient = @import("modal_client.zig");
const KDBLogger = @import("kdb_logger.zig");
const Router = @import("router.zig");

const Config = struct {
    port: u16,
    cerebras_api_key: []const u8,
    cerebras_base_url: []const u8,
    dragonfly_url: []const u8,
    modal_base_url: []const u8,
    kdb_host: []const u8,
    kdb_port: u16,
    max_workers: usize,
};

const Server = struct {
    allocator: Allocator,
    config: Config,
    cerebras: *CerebrasClient,
    dragonfly: *DragonflyClient,
    modal: *ModalClient,
    kdb_logger: *KDBLogger,
    router: *Router,
    server: http.Server,
    running: std.atomic.Value(bool),

    pub fn init(allocator: Allocator, config: Config) !*Server {
        const self = try allocator.create(Server);
        self.* = .{
            .allocator = allocator,
            .config = config,
            .cerebras = try CerebrasClient.init(allocator, config.cerebras_base_url, config.cerebras_api_key),
            .dragonfly = try DragonflyClient.init(allocator, config.dragonfly_url),
            .modal = try ModalClient.init(allocator, config.modal_base_url),
            .kdb_logger = try KDBLogger.init(allocator, config.kdb_host, config.kdb_port),
            .router = try Router.init(allocator),
            .server = undefined,
            .running = std.atomic.Value(bool).init(true),
        };
        return self;
    }

    pub fn deinit(self: *Server) void {
        self.cerebras.deinit();
        self.dragonfly.deinit();
        self.modal.deinit();
        self.kdb_logger.deinit();
        self.router.deinit();
        self.allocator.destroy(self);
    }

    pub fn start(self: *Server) !void {
        const address = try net.Address.parseIp("0.0.0.0", self.config.port);
        self.server = try address.listen(.{
            .reuse_address = true,
            .reuse_port = true,
        });

        std.log.info("Server listening on port {d}", .{self.config.port});

        while (self.running.load(.acquire)) {
            const conn = self.server.accept() catch |err| {
                std.log.err("Accept error: {}", .{err});
                continue;
            };

            const thread = try Thread.spawn(.{}, handleConnection, .{ self, conn });
            thread.detach();
        }
    }

    fn handleConnection(self: *Server, conn: net.Server.Connection) void {
        defer conn.stream.close();

        var buf: [8192]u8 = undefined;
        const read_size = conn.stream.read(&buf) catch |err| {
            std.log.err("Read error: {}", .{err});
            return;
        };

        if (read_size == 0) return;

        const request = buf[0..read_size];
        self.processRequest(conn.stream, request) catch |err| {
            std.log.err("Process error: {}", .{err});
            const error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\n\r\n";
            _ = conn.stream.write(error_response) catch {};
        };
    }

    fn processRequest(self: *Server, stream: net.Stream, request: []const u8) !void {
        var lines = std.mem.split(u8, request, "\r\n");
        const request_line = lines.next() orelse return error.InvalidRequest;

        var parts = std.mem.split(u8, request_line, " ");
        const method = parts.next() orelse return error.InvalidRequest;
        const path = parts.next() orelse return error.InvalidRequest;

        if (std.mem.eql(u8, method, "GET") and std.mem.startsWith(u8, path, "/search")) {
            try self.handleSearch(stream, path);
        } else if (std.mem.eql(u8, method, "GET") and std.mem.eql(u8, path, "/health")) {
            try self.handleHealth(stream);
        } else if (std.mem.eql(u8, method, "GET") and std.mem.eql(u8, path, "/stats")) {
            try self.handleStats(stream);
        } else {
            const response = "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n";
            _ = try stream.write(response);
        }
    }

    fn handleSearch(self: *Server, stream: net.Stream, path: []const u8) !void {
        var query_string: ?[]const u8 = null;
        if (std.mem.indexOf(u8, path, "?")) |idx| {
            query_string = path[idx + 1 ..];
        }

        if (query_string == null) {
            const response = "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
            _ = try stream.write(response);
            return;
        }

        var q_param: ?[]const u8 = null;
        var deep_research = false;
        var user_id: ?[]const u8 = null;

        var params = std.mem.split(u8, query_string.?, "&");
        while (params.next()) |param| {
            if (std.mem.indexOf(u8, param, "=")) |eq_idx| {
                const key = param[0..eq_idx];
                const value = param[eq_idx + 1 ..];
                if (std.mem.eql(u8, key, "q")) {
                    q_param = value;
                } else if (std.mem.eql(u8, key, "deep_research")) {
                    deep_research = std.mem.eql(u8, value, "true");
                } else if (std.mem.eql(u8, key, "user_id")) {
                    user_id = value;
                }
            }
        }

        if (q_param == null) {
            const response = "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
            _ = try stream.write(response);
            return;
        }

        const query = try std.Uri.unescapeString(self.allocator, q_param.?);
        defer self.allocator.free(query);

        var hash_buf: [32]u8 = undefined;
        crypto.hash.sha2.Sha256.hash(query, &hash_buf, .{});
        var cache_key_buf: [128]u8 = undefined;
        const cache_key = try std.fmt.bufPrint(&cache_key_buf, "cache:search:{s}", .{std.fmt.fmtSliceHexLower(&hash_buf)});

        const cached = self.dragonfly.get(cache_key) catch null;
        if (cached) |cached_data| {
            defer self.allocator.free(cached_data);
            const header = "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\n\r\n";
            _ = try stream.write(header);
            _ = try stream.write(cached_data);
            return;
        }

        const header = "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\n\r\n";
        _ = try stream.write(header);

        const route_decision = try self.router.decideRoute(query, deep_research);

        const qwen_response = try self.cerebras.chatCompletion(.{
            .model = "qwen-3-235b-a22b-instruct-2507",
            .messages = &[_]CerebrasClient.Message{
                .{ .role = "system", .content = "You are a reranker on numeric document ids, only respond with a JSON list of selected ids in descending relevance order." },
                .{ .role = "user", .content = query },
            },
            .temperature = 0.1,
            .max_completion_tokens = 200,
            .stream = false,
        });
        defer self.allocator.free(qwen_response);

        const doc_ids = try std.json.parseFromSlice([]u32, self.allocator, qwen_response, .{});
        defer doc_ids.deinit();

        const embeddings = try self.modal.embeddingEncode(&[_][]const u8{query});
        defer self.allocator.free(embeddings);

        const search_results = try self.modal.vectorSearch(embeddings[0], doc_ids.value, 20);
        defer self.allocator.free(search_results);

        const model = if (route_decision.is_complex) "zai-glm-4.7" else "gpt-oss-120b";
        const max_tokens: u32 = if (route_decision.is_complex) 40000 else 8000;

        var context_buf = std.ArrayList(u8).init(self.allocator);
        defer context_buf.deinit();

        for (search_results) |result| {
            try context_buf.writer().print("Doc {d}: {s}\n", .{ result.id, result.content });
        }

        const stream_response = try self.cerebras.chatCompletionStream(.{
            .model = model,
            .messages = &[_]CerebrasClient.Message{
                .{ .role = "system", .content = "You are a helpful search assistant." },
                .{ .role = "user", .content = query },
                .{ .role = "assistant", .content = context_buf.items },
            },
            .temperature = 0.3,
            .max_completion_tokens = max_tokens,
            .stream = true,
        });
        defer stream_response.deinit();

        var response_buffer = std.ArrayList(u8).init(self.allocator);
        defer response_buffer.deinit();

        while (try stream_response.next()) |chunk| {
            var event_buf: [2048]u8 = undefined;
            const event = try std.fmt.bufPrint(&event_buf, "event: chunk\ndata: {s}\n\n", .{chunk});
            _ = try stream.write(event);
            try response_buffer.appendSlice(chunk);
        }

        const ttl: u32 = if (route_decision.is_complex) 21600 else 3600;
        try self.dragonfly.setex(cache_key, ttl, response_buffer.items);

        try self.kdb_logger.log(.{
            .event_type = "search",
            .query = query,
            .model = model,
            .is_complex = route_decision.is_complex,
            .doc_count = search_results.len,
            .user_id = user_id,
        });
    }

    fn handleHealth(self: *Server, stream: net.Stream) !void {
        _ = self;
        const response = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 15\r\n\r\n{\"status\":\"ok\"}";
        _ = try stream.write(response);
    }

    fn handleStats(self: *Server, stream: net.Stream) !void {
        const stats = try self.dragonfly.info();
        defer self.allocator.free(stats);

        var response_buf: [4096]u8 = undefined;
        const response = try std.fmt.bufPrint(&response_buf, "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {d}\r\n\r\n{s}", .{ stats.len, stats });
        _ = try stream.write(response);
    }

    pub fn stop(self: *Server) void {
        self.running.store(false, .release);
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const config = Config{
        .port = 8080,
        .cerebras_api_key = std.posix.getenv("CEREBRAS_API_KEY") orelse return error.MissingApiKey,
        .cerebras_base_url = std.posix.getenv("CEREBRAS_BASE_URL") orelse "https://api.cerebras.ai/v1",
        .dragonfly_url = std.posix.getenv("DRAGONFLY_URL") orelse "redis://localhost:6379",
        .modal_base_url = std.posix.getenv("MODAL_BASE_URL") orelse return error.MissingModalUrl,
        .kdb_host = std.posix.getenv("KDB_HOST") orelse "localhost",
        .kdb_port = 5001,
        .max_workers = 100,
    };

    const server = try Server.init(allocator, config);
    defer server.deinit();

    const sigint = try std.posix.sigaction(std.posix.SIG.INT, &.{
        .handler = .{ .handler = handleSignal },
        .mask = std.posix.empty_sigset,
        .flags = 0,
    }, null);
    _ = sigint;

    try server.start();
}

fn handleSignal(sig: c_int) callconv(.C) void {
    _ = sig;
    std.posix.exit(0);
}


zig
const std = @import("std");
const http = std.http;
const Allocator = std.mem.Allocator;

pub const Message = struct {
    role: []const u8,
    content: []const u8,
};

pub const CompletionOptions = struct {
    model: []const u8,
    messages: []const Message,
    temperature: f32,
    max_completion_tokens: u32,
    stream: bool,
};

pub const StreamResponse = struct {
    allocator: Allocator,
    client: *http.Client,
    response: http.Client.Response,
    buffer: std.ArrayList(u8),

    pub fn deinit(self: *StreamResponse) void {
        self.buffer.deinit();
        self.response.deinit();
        self.allocator.destroy(self);
    }

    pub fn next(self: *StreamResponse) !?[]const u8 {
        self.buffer.clearRetainingCapacity();

        var line_buf: [4096]u8 = undefined;
        const reader = self.response.reader();

        while (true) {
            const line = reader.readUntilDelimiter(&line_buf, '\n') catch |err| {
                if (err == error.EndOfStream) return null;
                return err;
            };

            if (std.mem.startsWith(u8, line, "data: ")) {
                const data = line[6..];
                if (std.mem.eql(u8, data, "[DONE]")) return null;
                return data;
            }
        }
    }
};

pub const CerebrasClient = struct {
    allocator: Allocator,
    base_url: []const u8,
    api_key: []const u8,
    http_client: http.Client,

    pub fn init(allocator: Allocator, base_url: []const u8, api_key: []const u8) !*CerebrasClient {
        const self = try allocator.create(CerebrasClient);
        self.* = .{
            .allocator = allocator,
            .base_url = base_url,
            .api_key = api_key,
            .http_client = http.Client{ .allocator = allocator },
        };
        return self;
    }

    pub fn deinit(self: *CerebrasClient) void {
        self.http_client.deinit();
        self.allocator.destroy(self);
    }

    pub fn chatCompletion(self: *CerebrasClient, options: CompletionOptions) ![]const u8 {
        var json_buf = std.ArrayList(u8).init(self.allocator);
        defer json_buf.deinit();

        try json_buf.appendSlice("{\"model\":\"");
        try json_buf.appendSlice(options.model);
        try json_buf.appendSlice("\",\"messages\":[");

        for (options.messages, 0..) |msg, i| {
            if (i > 0) try json_buf.appendSlice(",");
            try json_buf.appendSlice("{\"role\":\"");
            try json_buf.appendSlice(msg.role);
            try json_buf.appendSlice("\",\"content\":\"");
            try self.escapeJson(&json_buf, msg.content);
            try json_buf.appendSlice("\"}");
        }

        try json_buf.appendSlice("],\"temperature\":");
        try std.fmt.format(json_buf.writer(), "{d}", .{options.temperature});
        try json_buf.appendSlice(",\"max_completion_tokens\":");
        try std.fmt.format(json_buf.writer(), "{d}", .{options.max_completion_tokens});
        try json_buf.appendSlice(",\"stream\":");
        try json_buf.appendSlice(if (options.stream) "true" else "false");
        try json_buf.appendSlice("}");

        var url_buf: [256]u8 = undefined;
        const url = try std.fmt.bufPrint(&url_buf, "{s}/chat/completions", .{self.base_url});
        const uri = try std.Uri.parse(url);

        var headers = http.Headers{ .allocator = self.allocator };
        defer headers.deinit();
        try headers.append("Authorization", try std.fmt.allocPrint(self.allocator, "Bearer {s}", .{self.api_key}));
        defer self.allocator.free(headers.list.items[0].value);
        try headers.append("Content-Type", "application/json");

        var retries: u8 = 0;
        while (retries < 3) : (retries += 1) {
            var request = try self.http_client.request(.POST, uri, headers, .{});
            defer request.deinit();

            request.transfer_encoding = .{ .content_length = json_buf.items.len };

            try request.start();
            try request.writer().writeAll(json_buf.items);
            try request.finish();

            try request.wait();

            if (request.response.status == .ok) {
                var response_buf = std.ArrayList(u8).init(self.allocator);
                errdefer response_buf.deinit();

                const reader = request.reader();
                try reader.readAllArrayList(&response_buf, 1024 * 1024 * 10);

                const parsed = try std.json.parseFromSlice(std.json.Value, self.allocator, response_buf.items, .{});
                defer parsed.deinit();

                const choices = parsed.value.object.get("choices") orelse return error.InvalidResponse;
                const first_choice = choices.array.items[0];
                const message = first_choice.object.get("message") orelse return error.InvalidResponse;
                const content = message.object.get("content") orelse return error.InvalidResponse;

                return try self.allocator.dupe(u8, content.string);
            }

            if (retries < 2) {
                const backoff_ms = @as(u64, 100) << @intCast(retries);
                std.time.sleep(backoff_ms * std.time.ns_per_ms);
            }
        }

        return error.MaxRetriesExceeded;
    }

    pub fn chatCompletionStream(self: *CerebrasClient, options: CompletionOptions) !*StreamResponse {
        var json_buf = std.ArrayList(u8).init(self.allocator);
        defer json_buf.deinit();

        try json_buf.appendSlice("{\"model\":\"");
        try json_buf.appendSlice(options.model);
        try json_buf.appendSlice("\",\"messages\":[");

        for (options.messages, 0..) |msg, i| {
            if (i > 0) try json_buf.appendSlice(",");
            try json_buf.appendSlice("{\"role\":\"");
            try json_buf.appendSlice(msg.role);
            try json_buf.appendSlice("\",\"content\":\"");
            try self.escapeJson(&json_buf, msg.content);
            try json_buf.appendSlice("\"}");
        }

        try json_buf.appendSlice("],\"temperature\":");
        try std.fmt.format(json_buf.writer(), "{d}", .{options.temperature});
        try json_buf.appendSlice(",\"max_completion_tokens\":");
        try std.fmt.format(json_buf.writer(), "{d}", .{options.max_completion_tokens});
        try json_buf.appendSlice(",\"stream\":true}");

        var url_buf: [256]u8 = undefined;
        const url = try std.fmt.bufPrint(&url_buf, "{s}/chat/completions", .{self.base_url});
        const uri = try std.Uri.parse(url);

        var headers = http.Headers{ .allocator = self.allocator };
        defer headers.deinit();
        try headers.append("Authorization", try std.fmt.allocPrint(self.allocator, "Bearer {s}", .{self.api_key}));
        defer self.allocator.free(headers.list.items[0].value);
        try headers.append("Content-Type", "application/json");

        var request = try self.http_client.request(.POST, uri, headers, .{});
        request.transfer_encoding = .{ .content_length = json_buf.items.len };

        try request.start();
        try request.writer().writeAll(json_buf.items);
        try request.finish();

        try request.wait();

        const stream = try self.allocator.create(StreamResponse);
        stream.* = .{
            .allocator = self.allocator,
            .client = &self.http_client,
            .response = request.response,
            .buffer = std.ArrayList(u8).init(self.allocator),
        };

        return stream;
    }

    fn escapeJson(self: *CerebrasClient, buf: *std.ArrayList(u8), str: []const u8) !void {
        _ = self;
        for (str) |c| {
            switch (c) {
                '"' => try buf.appendSlice("\\\""),
                '\\' => try buf.appendSlice("\\\\"),
                '\n' => try buf.appendSlice("\\n"),
                '\r' => try buf.appendSlice("\\r"),
                '\t' => try buf.appendSlice("\\t"),
                else => try buf.append(c),
            }
        }
    }
};


