const std = @import("std");
const net = std.net;
const Allocator = std.mem.Allocator;

pub const DragonflyClient = struct {
    allocator: Allocator,
    address: net.Address,
    stream: ?net.Stream,

    pub fn init(allocator: Allocator, url: []const u8) !*DragonflyClient {
        _ = url;
        const self = try allocator.create(DragonflyClient);
        self.* = .{
            .allocator = allocator,
            .address = try net.Address.parseIp("127.0.0.1", 6379),
            .stream = null,
        };
        return self;
    }

    pub fn deinit(self: *DragonflyClient) void {
        if (self.stream) |s| s.close();
        self.allocator.destroy(self);
    }

    fn connect(self: *DragonflyClient) !void {
        if (self.stream != null) return;
        self.stream = try net.tcpConnectToAddress(self.address);
    }

    pub fn get(self: *DragonflyClient, key: []const u8) !?[]const u8 {
        try self.connect();
        const stream = self.stream.?;

        var cmd_buf: [512]u8 = undefined;
        const cmd = try std.fmt.bufPrint(&cmd_buf, "*2\r\n$3\r\nGET\r\n${d}\r\n{s}\r\n", .{ key.len, key });
        _ = try stream.write(cmd);

        var response_buf: [8192]u8 = undefined;
        const read_size = try stream.read(&response_buf);
        const response = response_buf[0..read_size];

        if (response[0] == '$') {
            if (response[1] == '-' and response[2] == '1') return null;

            var len_end: usize = 1;
            while (len_end < response.len and response[len_end] != '\r') : (len_end += 1) {}
            const len = try std.fmt.parseInt(usize, response[1..len_end], 10);

            const data_start = len_end + 2;
            const data = response[data_start .. data_start + len];
            return try self.allocator.dupe(u8, data);
        }

        return null;
    }

    pub fn setex(self: *DragonflyClient, key: []const u8, seconds: u32, value: []const u8) !void {
        try self.connect();
        const stream = self.stream.?;

        var cmd_buf: [1024]u8 = undefined;
        const cmd = try std.fmt.bufPrint(&cmd_buf, "*4\r\n$5\r\nSETEX\r\n${d}\r\n{s}\r\n${d}\r\n{d}\r\n${d}\r\n{s}\r\n", .{ key.len, key, @as(usize, @intCast(seconds)), seconds, value.len, value });
        _ = try stream.write(cmd);

        var response_buf: [256]u8 = undefined;
        _ = try stream.read(&response_buf);
    }

    pub fn bfReserve(self: *DragonflyClient, key: []const u8, error_rate: f64, capacity: u64) !void {
        try self.connect();
        const stream = self.stream.?;

        var cmd_buf: [512]u8 = undefined;
        const cmd = try std.fmt.bufPrint(&cmd_buf, "*4\r\n$10\r\nBF.RESERVE\r\n${d}\r\n{s}\r\n$5\r\n{d:.4}\r\n${d}\r\n{d}\r\n", .{ key.len, key, error_rate, @as(usize, @intCast(capacity)), capacity });
        _ = try stream.write(cmd);

        var response_buf: [256]u8 = undefined;
        _ = try stream.read(&response_buf);
    }

    pub fn bfAdd(self: *DragonflyClient, key: []const u8, item: []const u8) !bool {
        try self.connect();
        const stream = self.stream.?;

        var cmd_buf: [1024]u8 = undefined;
        const cmd = try std.fmt.bufPrint(&cmd_buf, "*3\r\n$6\r\nBF.ADD\r\n${d}\r\n{s}\r\n${d}\r\n{s}\r\n", .{ key.len, key, item.len, item });
        _ = try stream.write(cmd);

        var response_buf: [256]u8 = undefined;
        const read_size = try stream.read(&response_buf);
        const response = response_buf[0..read_size];

        return response[0] == ':' and response[1] == '1';
    }

    pub fn bfExists(self: *DragonflyClient, key: []const u8, item: []const u8) !bool {
        try self.connect();
        const stream = self.stream.?;

        var cmd_buf: [1024]u8 = undefined;
        const cmd = try std.fmt.bufPrint(&cmd_buf, "*3\r\n$9\r\nBF.EXISTS\r\n${d}\r\n{s}\r\n${d}\r\n{s}\r\n", .{ key.len, key, item.len, item });
        _ = try stream.write(cmd);

        var response_buf: [256]u8 = undefined;
        const read_size = try stream.read(&response_buf);
        const response = response_buf[0..read_size];

        return response[0] == ':' and response[1] == '1';
    }

    pub fn info(self: *DragonflyClient) ![]const u8 {
        try self.connect();
        const stream = self.stream.?;

        const cmd = "*1\r\n$4\r\nINFO\r\n";
        _ = try stream.write(cmd);

        var response = std.ArrayList(u8).init(self.allocator);
        errdefer response.deinit();

        var buf: [4096]u8 = undefined;
        const read_size = try stream.read(&buf);

        if (buf[0] == '$') {
            var len_end: usize = 1;
            while (len_end < read_size and buf[len_end] != '\r') : (len_end += 1) {}
            const len = try std.fmt.parseInt(usize, buf[1..len_end], 10);
            const data_start = len_end + 2;
            try response.appendSlice(buf[data_start .. data_start + len]);
        }

        return response.toOwnedSlice();
    }
};


