const std = @import("std");
const Allocator = std.mem.Allocator;

pub const Router = struct {
    allocator: Allocator,
    complex_keywords: []const []const u8,

    pub fn init(allocator: Allocator) !*Router {
        const self = try allocator.create(Router);
        self.* = .{
            .allocator = allocator,
            .complex_keywords = &[_][]const u8{
                "compare",
                "vs",
                "implement",
                "code",
                "analyze",
                "explain deeply",
                "difference between",
                "how does",
                "why is",
                "architecture",
            },
        };
        return self;
    }

    pub fn deinit(self: *Router) void {
        self.allocator.destroy(self);
    }

    pub const RouteDecision = struct {
        is_complex: bool,
        reason: []const u8,
    };

    pub fn decideRoute(self: *Router, query: []const u8, deep_research: bool) !RouteDecision {
        if (deep_research) {
            return RouteDecision{
                .is_complex = true,
                .reason = "deep_research_flag",
            };
        }

        if (query.len > 200) {
            return RouteDecision{
                .is_complex = true,
                .reason = "long_query",
            };
        }

        const query_lower = try std.ascii.allocLowerString(self.allocator, query);
        defer self.allocator.free(query_lower);

        for (self.complex_keywords) |keyword| {
            if (std.mem.indexOf(u8, query_lower, keyword)) |_| {
                return RouteDecision{
                    .is_complex = true,
                    .reason = "keyword_match",
                };
            }
        }

        return RouteDecision{
            .is_complex = false,
            .reason = "simple_query",
        };
    }
};


