const std = @import("std");
const http = std.http;
const Allocator = std.mem.Allocator;

pub const SearchResult = struct {
    id: u32,
    score: f32,
    content: []const u8,
};

pub const ModalClient = struct {
    allocator: Allocator,
    base_url: []const u8,
    http_client: http.Client,

    pub fn init(allocator: Allocator, base_url: []const u8) !*ModalClient {
        const self = try allocator.create(ModalClient);
        self.* = .{
            .allocator = allocator,
            .base_url = base_url,
            .http_client = http.Client{ .allocator = allocator },
        };
        return self;
    }

    pub fn deinit(self: *ModalClient) void {
        self.http_client.deinit();
        self.allocator.destroy(self);
    }

    pub fn embeddingEncode(self: *ModalClient, texts: []const []const u8) ![]const []const f32 {
        var json_buf = std.ArrayList(u8).init(self.allocator);
        defer json_buf.deinit();

        try json_buf.appendSlice("{\"texts\":[");
        for (texts, 0..) |text, i| {
            if (i > 0) try json_buf.appendSlice(",");
            try json_buf.appendSlice("\"");
            try self.escapeJson(&json_buf, text);
            try json_buf.appendSlice("\"");
        }
        try json_buf.appendSlice("]}");

        var url_buf: [256]u8 = undefined;
        const url = try std.fmt.bufPrint(&url_buf, "{s}/embedding_encode", .{self.base_url});
        const uri = try std.Uri.parse(url);

        var headers = http.Headers{ .allocator = self.allocator };
        defer headers.deinit();
        try headers.append("Content-Type", "application/json");

        var request = try self.http_client.request(.POST, uri, headers, .{});
        defer request.deinit();

        request.transfer_encoding = .{ .content_length = json_buf.items.len };

        try request.start();
        try request.writer().writeAll(json_buf.items);
        try request.finish();
        try request.wait();

        var response_buf = std.ArrayList(u8).init(self.allocator);
        defer response_buf.deinit();

        const reader = request.reader();
        try reader.readAllArrayList(&response_buf, 1024 * 1024 * 10);

        const parsed = try std.json.parseFromSlice(std.json.Value, self.allocator, response_buf.items, .{});
        defer parsed.deinit();

        const embeddings_array = parsed.value.object.get("embeddings") orelse return error.InvalidResponse;
        const result = try self.allocator.alloc([]const f32, embeddings_array.array.items.len);

        for (embeddings_array.array.items, 0..) |embedding, i| {
            const vec = try self.allocator.alloc(f32, embedding.array.items.len);
            for (embedding.array.items, 0..) |val, j| {
                vec[j] = @floatCast(val.float);
            }
            result[i] = vec;
        }

        return result;
    }

    pub fn vectorSearch(self: *ModalClient, query_embedding: []const f32, doc_ids: []const u32, top_k: u32) ![]const SearchResult {
        var json_buf = std.ArrayList(u8).init(self.allocator);
        defer json_buf.deinit();

        try json_buf.appendSlice("{\"query_embedding\":[");
        for (query_embedding, 0..) |val, i| {
            if (i > 0) try json_buf.appendSlice(",");
            try std.fmt.format(json_buf.writer(), "{d}", .{val});
        }
        try json_buf.appendSlice("],\"doc_ids\":[");
        for (doc_ids, 0..) |id, i| {
            if (i > 0) try json_buf.appendSlice(",");
            try std.fmt.format(json_buf.writer(), "{d}", .{id});
        }
        try json_buf.appendSlice("],\"top_k\":");
        try std.fmt.format(json_buf.writer(), "{d}", .{top_k});
        try json_buf.appendSlice("}");

        var url_buf: [256]u8 = undefined;
        const url = try std.fmt.bufPrint(&url_buf, "{s}/vector_search", .{self.base_url});
        const uri = try std.Uri.parse(url);

        var headers = http.Headers{ .allocator = self.allocator };
        defer headers.deinit();
        try headers.append("Content-Type", "application/json");

        var request = try self.http_client.request(.POST, uri, headers, .{});
        defer request.deinit();

        request.transfer_encoding = .{ .content_length = json_buf.items.len };

        try request.start();
        try request.writer().writeAll(json_buf.items);
        try request.finish();
        try request.wait();

        var response_buf = std.ArrayList(u8).init(self.allocator);
        defer response_buf.deinit();

        const reader = request.reader();
        try reader.readAllArrayList(&response_buf, 1024 * 1024 * 10);

        const parsed = try std.json.parseFromSlice(std.json.Value, self.allocator, response_buf.items, .{});
        defer parsed.deinit();

        const results_array = parsed.value.object.get("results") orelse return error.InvalidResponse;
        const results = try self.allocator.alloc(SearchResult, results_array.array.items.len);

        for (results_array.array.items, 0..) |item, i| {
            const id = @as(u32, @intFromFloat(item.object.get("id").?.float));
            const score = @as(f32, @floatCast(item.object.get("score").?.float));
            const content = try self.allocator.dupe(u8, item.object.get("content").?.string);
            results[i] = .{ .id = id, .score = score, .content = content };
        }

        return results;
    }

    fn escapeJson(self: *ModalClient, buf: *std.ArrayList(u8), str: []const u8) !void {
        _ = self;
        for (str) |c| {
            switch (c) {
                '"' => try buf.appendSlice("\\\""),
                '\\' => try buf.appendSlice("\\\\"),
                '\n' => try buf.appendSlice("\\n"),
                '\r' => try buf.appendSlice("\\r"),
                '\t' => try buf.appendSlice("\\t"),
                else => try buf.append(c),
            }
        }
    }
};


