const std = @import("std");
const net = std.net;
const Allocator = std.mem.Allocator;

pub const LogEvent = struct {
    event_type: []const u8,
    query: ?[]const u8 = null,
    model: ?[]const u8 = null,
    is_complex: ?bool = null,
    doc_count: ?usize = null,
    user_id: ?[]const u8 = null,
};

pub const KDBLogger = struct {
    allocator: Allocator,
    address: net.Address,
    stream: ?net.Stream,
    buffer: std.ArrayList(u8),
    mutex: std.Thread.Mutex,

    pub fn init(allocator: Allocator, host: []const u8, port: u16) !*KDBLogger {
        _ = host;
        const self = try allocator.create(KDBLogger);
        self.* = .{
            .allocator = allocator,
            .address = try net.Address.parseIp("127.0.0.1", port),
            .stream = null,
            .buffer = std.ArrayList(u8).init(allocator),
            .mutex = std.Thread.Mutex{},
        };
        return self;
    }

    pub fn deinit(self: *KDBLogger) void {
        if (self.stream) |s| s.close();
        self.buffer.deinit();
        self.allocator.destroy(self);
    }

    fn connect(self: *KDBLogger) !void {
        if (self.stream != null) return;
        self.stream = try net.tcpConnectToAddress(self.address);
    }

    pub fn log(self: *KDBLogger, event: LogEvent) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        try self.connect();

        self.buffer.clearRetainingCapacity();
        try self.buffer.appendSlice(".u.upd[`metrics;(");

        try self.buffer.appendSlice("`");
        try self.buffer.appendSlice(event.event_type);
        try self.buffer.appendSlice(";");

        if (event.query) |q| {
            try self.buffer.appendSlice("\"");
            try self.buffer.appendSlice(q);
            try self.buffer.appendSlice("\";");
        } else {
            try self.buffer.appendSlice("\"\";");
        }

        if (event.model) |m| {
            try self.buffer.appendSlice("`");
            try self.buffer.appendSlice(m);
            try self.buffer.appendSlice(";");
        } else {
            try self.buffer.appendSlice("`;");
        }

        if (event.is_complex) |ic| {
            try self.buffer.appendSlice(if (ic) "1b;" else "0b;");
        } else {
            try self.buffer.appendSlice("0b;");
        }

        if (event.doc_count) |dc| {
            try std.fmt.format(self.buffer.writer(), "{d};", .{dc});
        } else {
            try self.buffer.appendSlice("0;");
        }

        if (event.user_id) |uid| {
            try self.buffer.appendSlice("\"");
            try self.buffer.appendSlice(uid);
            try self.buffer.appendSlice("\"");
        } else {
            try self.buffer.appendSlice("\"\"");
        }

        try self.buffer.appendSlice(")]\n");

        const stream = self.stream.?;
        _ = try stream.write(self.buffer.items);
    }
};


