import modal
import torch
import numpy as np
from transformers import AutoTokenizer, AutoModel
import os

app = modal.App("neural-embeddings")

image = (
    modal.Image.debian_slim()
    .pip_install(
        "torch",
        "transformers",
        "numpy",
        "sentencepiece",
        "accelerate"
    )
)

volume = modal.Volume.from_name("embeddings-cache", create_if_missing=True)

@app.cls(
    gpu="B200:4",
    image=image,
    volumes={"/cache": volume},
    secrets=[modal.Secret.from_name("huggingface-secret")],
    timeout=300,
    keep_warm=2,
    allow_concurrent_inputs=10,
)
class EmbeddingEncoder:
    @modal.enter()
    def load_model(self):
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        model_name = "BAAI/bge-large-en-v1.5"

        self.tokenizer = AutoTokenizer.from_pretrained(
            model_name,
            cache_dir="/cache"
        )
        self.model = AutoModel.from_pretrained(
            model_name,
            cache_dir="/cache",
            torch_dtype=torch.float16
        ).to(self.device)
        self.model.eval()

        self.max_length = 512
        self.embedding_dim = 1024

    @modal.method()
    def encode(self, texts: list[str]) -> list[list[float]]:
        with torch.no_grad():
            encoded_input = self.tokenizer(
                texts,
                padding=True,
                truncation=True,
                max_length=self.max_length,
                return_tensors="pt"
            ).to(self.device)

            model_output = self.model(**encoded_input)
            embeddings = model_output.last_hidden_state[:, 0]
            embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=1)

            return embeddings.cpu().numpy().tolist()

@app.function(
    image=image,
    secrets=[modal.Secret.from_name("modal-secret")],
)
@modal.web_endpoint(method="POST")
def embedding_encode(data: dict):
    texts = data.get("texts", [])
    if not texts:
        return {"error": "No texts provided"}, 400

    encoder = EmbeddingEncoder()
    embeddings = encoder.encode.remote(texts)

    return {"embeddings": embeddings}

@app.local_entrypoint()
def main():
    texts = ["Hello world", "Test embedding"]
    result = embedding_encode.remote({"texts": texts})
    print(result)


