import modal
import numpy as np
import torch
import faiss
import os
import pickle
from pathlib import Path

app = modal.App("neural-vector-search")

image = (
    modal.Image.debian_slim()
    .pip_install(
        "faiss-gpu",
        "numpy",
        "torch"
    )
    .apt_install("build-essential")
)

volume = modal.Volume.from_name("vector-index", create_if_missing=True)

@app.cls(
    gpu="B200:8",
    image=image,
    volumes={"/index": volume},
    timeout=600,
    keep_warm=1,
    allow_concurrent_inputs=20,
)
class VectorSearchEngine:
    @modal.enter()
    def load_index(self):
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.embedding_dim = 1024

        index_path = Path("/index/faiss.index")
        metadata_path = Path("/index/metadata.pkl")

        if index_path.exists():
            self.index = faiss.read_index(str(index_path))

            res = faiss.StandardGpuResources()
            self.gpu_index = faiss.index_cpu_to_gpu(res, 0, self.index)

            with open(metadata_path, "rb") as f:
                self.metadata = pickle.load(f)
        else:
            quantizer = faiss.IndexFlatIP(self.embedding_dim)
            self.index = faiss.IndexIVFPQ(
                quantizer,
                self.embedding_dim,
                1024,
                64,
                8
            )
            self.index.nprobe = 32

            res = faiss.StandardGpuResources()
            self.gpu_index = faiss.index_cpu_to_gpu(res, 0, self.index)

            self.metadata = {}

    @modal.method()
    def search(self, query_embedding: list[float], doc_ids: list[int], top_k: int = 20) -> list[dict]:
        query_array = np.array([query_embedding], dtype=np.float32)
        faiss.normalize_L2(query_array)

        distances, indices = self.gpu_index.search(query_array, min(top_k * 2, self.gpu_index.ntotal))

        results = []
        doc_id_set = set(doc_ids) if doc_ids else None

        for i in range(indices.shape[1]):
            idx = int(indices[0, i])
            if idx < 0:
                continue

            doc_id = self.metadata.get(idx, {}).get("doc_id", idx)

            if doc_id_set and doc_id not in doc_id_set:
                continue

            content = self.metadata.get(idx, {}).get("content", "")
            score = float(distances[0, i])

            results.append({
                "id": doc_id,
                "score": score,
                "content": content
            })

            if len(results) >= top_k:
                break

        return results

    @modal.method()
    def add_vectors(self, embeddings: list[list[float]], doc_ids: list[int], contents: list[str]):
        vectors = np.array(embeddings, dtype=np.float32)
        faiss.normalize_L2(vectors)

        if not self.index.is_trained:
            self.index.train(vectors)

        start_idx = self.index.ntotal
        self.gpu_index.add(vectors)

        for i, (doc_id, content) in enumerate(zip(doc_ids, contents)):
            self.metadata[start_idx + i] = {
                "doc_id": doc_id,
                "content": content
            }

        self.save_index()

    def save_index(self):
        cpu_index = faiss.index_gpu_to_cpu(self.gpu_index)
        faiss.write_index(cpu_index, "/index/faiss.index")

        with open("/index/metadata.pkl", "wb") as f:
            pickle.dump(self.metadata, f)

        volume.commit()

@app.function(
    image=image,
    secrets=[modal.Secret.from_name("modal-secret")],
)
@modal.web_endpoint(method="POST")
def vector_search(data: dict):
    query_embedding = data.get("query_embedding")
    doc_ids = data.get("doc_ids", [])
    top_k = data.get("top_k", 20)

    if not query_embedding:
        return {"error": "No query_embedding provided"}, 400

    engine = VectorSearchEngine()
    results = engine.search.remote(query_embedding, doc_ids, top_k)

    return {"results": results}

@app.function(
    image=image,
    schedule=modal.Cron("0 2 * * *"),
    secrets=[modal.Secret.from_name("postgres-secret")],
    timeout=7200,
)
def batch_indexer():
    import psycopg2

    conn = psycopg2.connect(os.environ["POSTGRES_DSN"])
    cur = conn.cursor()

    cur.execute("""
        SELECT id, content 
        FROM documents 
        WHERE indexed = false 
        ORDER BY id 
        LIMIT 10000
    """)

    rows = cur.fetchall()

    if not rows:
        print("No new documents to index")
        return

    doc_ids = [row[0] for row in rows]
    contents = [row[1] for row in rows]

    from embedding_encode import EmbeddingEncoder
    encoder = EmbeddingEncoder()
    embeddings = encoder.encode.remote(contents)

    engine = VectorSearchEngine()
    engine.add_vectors.remote(embeddings, doc_ids, contents)

    cur.execute("""
        UPDATE documents 
        SET indexed = true 
        WHERE id = ANY(%s)
    """, (doc_ids,))

    conn.commit()
    cur.close()
    conn.close()

    print(f"Indexed {len(doc_ids)} documents")

@app.local_entrypoint()
def main():
    query_embedding = [0.1] * 1024
    result = vector_search.remote({
        "query_embedding": query_embedding,
        "doc_ids": [],
        "top_k": 10
    })
    print(result)


