import modal
import subprocess
import os
import json

app = modal.App("neural-graph-compute")

image = (
    modal.Image.debian_slim()
    .apt_install(
        "build-essential",
        "cuda-toolkit-12-3",
        "git"
    )
    .run_commands(
        "git clone https://github.com/HigherOrderCO/Bend /bend",
        "cd /bend && cargo build --release --target=x86_64-unknown-linux-gnu"
    )
)

volume = modal.Volume.from_name("graph-data", create_if_missing=True)

@app.cls(
    gpu="B200:8",
    image=image,
    volumes={"/data": volume},
    timeout=1800,
    keep_warm=1,
)
class GraphCompute:
    @modal.enter()
    def setup(self):
        self.bend_path = "/bend/target/release/bend"
        self.scripts_dir = "/data/scripts"
        os.makedirs(self.scripts_dir, exist_ok=True)

    @modal.method()
    def pagerank(self, edges: list[tuple[int, int]], num_nodes: int, iterations: int = 20, damping: float = 0.85) -> dict[int, float]:
        script = f"""
def pagerank(edges, num_nodes, iterations, damping):
  ranks = {{i: 1.0 / num_nodes for i in range(num_nodes)}}

  for _ in range(iterations):
    new_ranks = {{i: (1 - damping) / num_nodes for i in range(num_nodes)}}

    for src, dst in edges:
      out_degree = len([e for e in edges if e[0] == src])
      if out_degree > 0:
        contribution = ranks[src] / out_degree
        new_ranks[dst] = new_ranks[dst] + damping * contribution

    ranks = new_ranks

  return ranks

result = pagerank({edges}, {num_nodes}, {iterations}, {damping})
"""

        script_path = f"{self.scripts_dir}/pagerank.bend"
        with open(script_path, "w") as f:
            f.write(script)

        result = subprocess.run(
            [self.bend_path, "run-cu", script_path],
            capture_output=True,
            text=True,
            timeout=300
        )

        if result.returncode != 0:
            raise RuntimeError(f"Bend execution failed: {result.stderr}")

        return json.loads(result.stdout)

    @modal.method()
    def connected_components(self, edges: list[tuple[int, int]], num_nodes: int) -> dict[int, int]:
        script = f"""
def union_find(parent, x):
  if parent[x] != x:
    parent[x] = union_find(parent, parent[x])
  return parent[x]

def connected_components(edges, num_nodes):
  parent = {{i: i for i in range(num_nodes)}}

  for src, dst in edges:
    root_src = union_find(parent, src)
    root_dst = union_find(parent, dst)
    if root_src != root_dst:
      parent[root_src] = root_dst

  components = {{}}
  for i in range(num_nodes):
    root = union_find(parent, i)
    components[i] = root

  return components

result = connected_components({edges}, {num_nodes})
"""

        script_path = f"{self.scripts_dir}/cc.bend"
        with open(script_path, "w") as f:
            f.write(script)

        result = subprocess.run(
            [self.bend_path, "run-cu", script_path],
            capture_output=True,
            text=True,
            timeout=300
        )

        if result.returncode != 0:
            raise RuntimeError(f"Bend execution failed: {result.stderr}")

        return json.loads(result.stdout)

    @modal.method()
    def louvain(self, edges: list[tuple[int, int]], num_nodes: int) -> dict[int, int]:
        script = f"""
def louvain(edges, num_nodes):
  community = {{i: i for i in range(num_nodes)}}

  improved = True
  while improved:
    improved = False
    for node in range(num_nodes):
      neighbors = [dst for src, dst in edges if src == node]
      if not neighbors:
        continue

      neighbor_communities = {{}}
      for neighbor in neighbors:
        c = community[neighbor]
        neighbor_communities[c] = neighbor_communities.get(c, 0) + 1

      best_community = max(neighbor_communities, key=neighbor_communities.get)

      if best_community != community[node]:
        community[node] = best_community
        improved = True

  return community

result = louvain({edges}, {num_nodes})
"""

        script_path = f"{self.scripts_dir}/louvain.bend"
        with open(script_path, "w") as f:
            f.write(script)

        result = subprocess.run(
            [self.bend_path, "run-cu", script_path],
            capture_output=True,
            text=True,
            timeout=600
        )

        if result.returncode != 0:
            raise RuntimeError(f"Bend execution failed: {result.stderr}")

        return json.loads(result.stdout)

@app.function(
    image=image,
    secrets=[modal.Secret.from_name("modal-secret")],
)
@modal.web_endpoint(method="POST")
def graph_compute(data: dict):
    operation = data.get("operation")
    edges = data.get("edges", [])
    num_nodes = data.get("num_nodes", 0)

    if not operation or not edges or num_nodes == 0:
        return {"error": "Invalid input"}, 400

    compute = GraphCompute()

    if operation == "pagerank":
        result = compute.pagerank.remote(edges, num_nodes)
    elif operation == "connected_components":
        result = compute.connected_components.remote(edges, num_nodes)
    elif operation == "louvain":
        result = compute.louvain.remote(edges, num_nodes)
    else:
        return {"error": f"Unknown operation: {operation}"}, 400

    return {"result": result}

@app.local_entrypoint()
def main():
    edges = [(0, 1), (1, 2), (2, 0), (3, 4)]
    result = graph_compute.remote({
        "operation": "pagerank",
        "edges": edges,
        "num_nodes": 5
    })
    print(result)


