import time
import statistics
import requests
import concurrent.futures

def benchmark_search():
    queries = [
        "quantum computing",
        "machine learning algorithms",
        "distributed systems",
        "neural networks",
        "database optimization"
    ]

    latencies = []

    for query in queries:
        start = time.time()
        response = requests.get(
            f"http://localhost:8080/search?q={query}",
            stream=True
        )

        for line in response.iter_lines():
            if line:
                pass

        latency = (time.time() - start) * 1000
        latencies.append(latency)

    print(f"Mean latency: {statistics.mean(latencies):.2f}ms")
    print(f"P50: {statistics.median(latencies):.2f}ms")
    print(f"P95: {sorted(latencies)[int(len(latencies)*0.95)]:.2f}ms")
    print(f"P99: {sorted(latencies)[int(len(latencies)*0.99)]:.2f}ms")

def benchmark_concurrent():
    def search():
        requests.get("http://localhost:8080/search?q=test", stream=True)

    concurrency_levels = [1, 10, 50, 100]

    for concurrency in concurrency_levels:
        start = time.time()
        with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as executor:
            futures = [executor.submit(search) for _ in range(100)]
            concurrent.futures.wait(futures)

        duration = time.time() - start
        throughput = 100 / duration
        print(f"Concurrency {concurrency}: {throughput:.2f} req/s")

if __name__ == "__main__":
    print("Sequential benchmark:")
    benchmark_search()
    print("\nConcurrent benchmark:")
    benchmark_concurrent()


