import std.stdio (STDOUT)
import std.env (arguments)
import std.string (String, ToString)
import std.process (sleep)
import std.time (Duration)
import std.net.http (Client, Method)

class async Main {
  fn async main {
    let args = arguments()
    let workers = if args.size > 0 { args.get(0).to_int.unwrap_or(100) } else { 100 }

    let frontier = UrlFrontier.new
    let fetcher = Fetcher.new
    let parser = Parser.new
    let dedup = Dedup.new
    let scheduler = Scheduler.new
    let storage = StorageClient.new
    let robots = RobotsChecker.new
    let metrics = Metrics.new

    STDOUT.new.print("Starting crawler with {workers} workers")

    frontier.initialize.await

    let mut active_workers = 0

    loop {
      if active_workers < workers {
        let url_opt = frontier.pop.await

        match url_opt {
          case Some(url) -> {
            active_workers = active_workers + 1

            process {
              let allowed = robots.is_allowed(url).await

              if allowed {
                let throttle_ok = scheduler.check_throttle(url).await

                if throttle_ok {
                  let html_opt = fetcher.fetch(url).await

                  match html_opt {
                    case Some(html) -> {
                      let is_dup = dedup.check(url, html).await

                      if is_dup.not {
                        let doc = parser.parse(url, html).await
                        storage.store(doc).await

                        doc.links.iter.each fn (link) {
                          frontier.push(link).await
                        }

                        metrics.increment_success.await
                      } else {
                        metrics.increment_duplicate.await
                      }
                    }
                    case None -> {
                      metrics.increment_error.await
                    }
                  }

                  scheduler.update_throttle(url).await
                }
              }

              active_workers = active_workers - 1
            }
          }
          case None -> {
            sleep(Duration.from_millis(100))
          }
        }
      } else {
        sleep(Duration.from_millis(10))
      }
    }
  }
}


