import std.string (String)
import std.net.socket (TcpClient)
import std.option (Option)
import std.fmt (fmt)

class pub async UrlFrontier {
  let @redis_host: String
  let @redis_port: Int

  fn pub static new -> UrlFrontier {
    UrlFrontier {
      @redis_host = "localhost",
      @redis_port = 6379
    }
  }

  fn async initialize {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*5\r\n$5\r\nZADD\r\n$14\r\nfrontier:queue\r\n$2\r\nNX\r\n$1\r\n0\r\n$23\r\nhttps://example.com\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 1024).unwrap

    client.close
  }

  fn pub async pop -> Option[String] {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*4\r\n$9\r\nZPOPMIN\r\n$14\r\nfrontier:queue\r\n$1\r\n1\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 4096).unwrap

    let response = String.from_bytes(buffer)

    client.close

    if response.starts_with?("*0") {
      return Option.None
    }

    let lines = response.split("\r\n")
    if lines.size > 2 {
      Option.Some(lines.get(2))
    } else {
      Option.None
    }
  }

  fn pub async push(url: String) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let score = 0
    let cmd = fmt("*4\r\n$4\r\nZADD\r\n$14\r\nfrontier:queue\r\n${url.size}\r\n{url}\r\n$1\r\n{score}\r\n")
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn pub async push_priority(url: String, priority: Int) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = fmt("*4\r\n$4\r\nZADD\r\n$14\r\nfrontier:queue\r\n$1\r\n{priority}\r\n${url.size}\r\n{url}\r\n")
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }
}


