import std.string (String)
import std.net.http (Client, Method, Request, Response)
import std.option (Option)
import std.time (Duration)

class pub async Fetcher {
  let @client: Client
  let @timeout: Duration
  let @max_retries: Int

  fn pub static new -> Fetcher {
    Fetcher {
      @client = Client.new,
      @timeout = Duration.from_secs(30),
      @max_retries = 3
    }
  }

  fn pub async fetch(url: String) -> Option[String] {
    let mut attempts = 0

    loop {
      if attempts >= @max_retries {
        return Option.None
      }

      attempts = attempts + 1

      let request = Request.new(method: Method.Get, url: url)
      request.header("User-Agent", "NeuralSearchBot/1.0")
      request.timeout(@timeout)

      let result = @client.execute(request).await

      match result {
        case Ok(response) -> {
          if response.status >= 200 and response.status < 300 {
            let body = response.body.to_string
            return Option.Some(body)
          } else if response.status >= 500 {
            let backoff = Duration.from_millis(100 * (2.pow(attempts)))
            sleep(backoff)
            next
          } else {
            return Option.None
          }
        }
        case Error(_) -> {
          if attempts < @max_retries {
            let backoff = Duration.from_millis(100 * (2.pow(attempts)))
            sleep(backoff)
            next
          } else {
            return Option.None
          }
        }
      }
    }
  }
}


