import std.string (String)
import std.option (Option)

class pub Document {
  let pub @url: String
  let pub @title: String
  let pub @content: String
  let pub @links: Array[String]
  let pub @lang: String
  let pub @timestamp: Int
}

class pub async Parser {
  fn pub static new -> Parser {
    Parser {}
  }

  fn pub async parse(url: String, html: String) -> Document {
    let title = extract_title(html)
    let content = clean_html(html)
    let links = extract_links(html, url)
    let lang = detect_language(content)
    let timestamp = current_timestamp()

    Document {
      @url = url,
      @title = title,
      @content = content,
      @links = links,
      @lang = lang,
      @timestamp = timestamp
    }
  }

  fn extract_title(html: String) -> String {
    let start_tag = "<title>"
    let end_tag = "</title>"

    let start_opt = html.index_of(start_tag)

    match start_opt {
      case Some(start_idx) -> {
        let content_start = start_idx + start_tag.size
        let end_opt = html.slice(content_start, html.size).index_of(end_tag)

        match end_opt {
          case Some(end_idx) -> {
            html.slice(content_start, content_start + end_idx).trim
          }
          case None -> "Untitled"
        }
      }
      case None -> "Untitled"
    }
  }

  fn clean_html(html: String) -> String {
    let mut text = html

    text = remove_between(text, "<script", "</script>")
    text = remove_between(text, "<style", "</style>")
    text = remove_between(text, "<!--", "-->")

    text = decode_entities(text)
    text = strip_tags(text)
    text = normalize_whitespace(text)

    text
  }

  fn remove_between(text: String, start: String, end: String) -> String {
    let mut result = text

    loop {
      let start_opt = result.index_of(start)

      match start_opt {
        case Some(start_idx) -> {
          let after_start = result.slice(start_idx, result.size)
          let end_opt = after_start.index_of(end)

          match end_opt {
            case Some(end_idx) -> {
              let before = result.slice(0, start_idx)
              let after = result.slice(start_idx + end_idx + end.size, result.size)
              result = before + after
            }
            case None -> break
          }
        }
        case None -> break
      }
    }

    result
  }

  fn decode_entities(text: String) -> String {
    let mut result = text

    result = result.replace("&amp;", "&")
    result = result.replace("&lt;", "<")
    result = result.replace("&gt;", ">")
    result = result.replace("&quot;", "\"")
    result = result.replace("&apos;", "'")
    result = result.replace("&nbsp;", " ")

    result
  }

  fn strip_tags(text: String) -> String {
    let mut result = String.new
    let mut in_tag = false

    text.chars.each fn (c) {
      if c == '<' {
        in_tag = true
      } else if c == '>' {
        in_tag = false
        result.push(' ')
      } else if in_tag.not {
        result.push(c)
      }
    }

    result
  }

  fn normalize_whitespace(text: String) -> String {
    let mut result = String.new
    let mut prev_space = false

    text.chars.each fn (c) {
      if c.is_whitespace {
        if prev_space.not {
          result.push(' ')
          prev_space = true
        }
      } else {
        result.push(c)
        prev_space = false
      }
    }

    result.trim
  }

  fn extract_links(html: String, base_url: String) -> Array[String] {
    let links = Array.new
    let mut pos = 0

    loop {
      let href_opt = html.slice(pos, html.size).index_of("href=\"")

      match href_opt {
        case Some(idx) -> {
          pos = pos + idx + 6
          let end_opt = html.slice(pos, html.size).index_of("\"")

          match end_opt {
            case Some(end_idx) -> {
              let link = html.slice(pos, pos + end_idx)
              let absolute = resolve_url(link, base_url)
              links.push(absolute)
              pos = pos + end_idx
            }
            case None -> break
          }
        }
        case None -> break
      }
    }

    links
  }

  fn resolve_url(url: String, base: String) -> String {
    if url.starts_with?("http://") or url.starts_with?("https://") {
      url
    } else if url.starts_with?("//") {
      "https:" + url
    } else if url.starts_with?("/") {
      let base_parts = base.split("/")
      base_parts.get(0) + "//" + base_parts.get(2) + url
    } else {
      let base_parts = base.split("/")
      let base_path = base_parts.slice(0, base_parts.size - 1).join("/")
      base_path + "/" + url
    }
  }

  fn detect_language(text: String) -> String {
    let sample = text.slice(0, min(text.size, 1000))

    let en_words = ["the", "is", "and", "of", "to", "a", "in", "that", "it", "with"]
    let mut en_count = 0

    en_words.iter.each fn (word) {
      if sample.contains?(word) {
        en_count = en_count + 1
      }
    }

    if en_count >= 5 {
      "en"
    } else {
      "unknown"
    }
  }

  fn current_timestamp -> Int {
    let now = std.time.Instant.now
    now.to_unix_timestamp
  }

  fn min(a: Int, b: Int) -> Int {
    if a < b { a } else { b }
  }
}


