import std.string (String)
import std.crypto (Hash, Hasher)
import std.net.socket (TcpClient)

class pub async Dedup {
  let @redis_host: String
  let @redis_port: Int

  fn pub static new -> Dedup {
    Dedup {
      @redis_host = "localhost",
      @redis_port = 6379
    }
  }

  fn pub async check(url: String, content: String) -> Bool {
    let url_hash = hash_string(url)
    let content_hash = hash_string(content)

    let bf_exists = bloom_filter_check(url_hash).await
    if bf_exists {
      return true
    }

    let exact_exists = exact_check(url_hash).await
    if exact_exists {
      return true
    }

    let simhash = compute_simhash(content)
    let near_dup = near_duplicate_check(simhash).await
    if near_dup {
      return true
    }

    bloom_filter_add(url_hash).await
    exact_add(url_hash, content_hash).await
    simhash_add(simhash).await

    false
  }

  fn hash_string(s: String) -> String {
    let mut hasher = Hasher.sha256
    hasher.write(s.to_byte_array)
    hasher.finish.to_hex_string
  }

  fn async bloom_filter_check(hash: String) -> Bool {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*3\r\n$9\r\nBF.EXISTS\r\n$11\r\ndedup:bloom\r\n${hash.size}\r\n{hash}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    let response = String.from_bytes(buffer)
    client.close

    response.starts_with?(":1")
  }

  fn async bloom_filter_add(hash: String) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*3\r\n$6\r\nBF.ADD\r\n$11\r\ndedup:bloom\r\n${hash.size}\r\n{hash}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn async exact_check(hash: String) -> Bool {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*2\r\n$7\r\nHEXISTS\r\n$11\r\ndedup:exact\r\n${hash.size}\r\n{hash}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    let response = String.from_bytes(buffer)
    client.close

    response.starts_with?(":1")
  }

  fn async exact_add(url_hash: String, content_hash: String) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*4\r\n$4\r\nHSET\r\n$11\r\ndedup:exact\r\n${url_hash.size}\r\n{url_hash}\r\n${content_hash.size}\r\n{content_hash}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn compute_simhash(text: String) -> Int {
    let words = text.split(" ")
    let mut v = Array.filled(with: 0, times: 64)

    words.iter.each fn (word) {
      let hash = hash_string(word).to_int_base(16).unwrap

      let mut i = 0
      loop {
        if i >= 64 { break }

        let bit = (hash >> i) & 1
        if bit == 1 {
          v.set(i, v.get(i) + 1)
        } else {
          v.set(i, v.get(i) - 1)
        }

        i = i + 1
      }
    }

    let mut simhash = 0
    let mut i = 0
    loop {
      if i >= 64 { break }

      if v.get(i) > 0 {
        simhash = simhash | (1 << i)
      }

      i = i + 1
    }

    simhash
  }

  fn async near_duplicate_check(simhash: Int) -> Bool {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*2\r\n$6\r\nSMEMBERS\r\n$13\r\ndedup:simhash\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 8192).unwrap

    let response = String.from_bytes(buffer)
    client.close

    let lines = response.split("\r\n")
    let mut i = 1

    loop {
      if i >= lines.size { break }

      let line = lines.get(i)
      if line.starts_with?("$") {
        let hash_str = lines.get(i + 1)
        let existing_hash = hash_str.to_int.unwrap_or(0)

        let distance = hamming_distance(simhash, existing_hash)
        if distance <= 3 {
          return true
        }

        i = i + 2
      } else {
        i = i + 1
      }
    }

    false
  }

  fn async simhash_add(simhash: Int) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let simhash_str = simhash.to_string
    let cmd = "*3\r\n$4\r\nSADD\r\n$13\r\ndedup:simhash\r\n${simhash_str.size}\r\n{simhash_str}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn hamming_distance(a: Int, b: Int) -> Int {
    let xor = a ^ b
    let mut count = 0
    let mut val = xor

    loop {
      if val == 0 { break }
      count = count + (val & 1)
      val = val >> 1
    }

    count
  }
}


