import std.string (String)
import std.net.socket (TcpClient)
import std.time (Duration, Instant)
import std.fmt (fmt)

class pub async Scheduler {
  let @redis_host: String
  let @redis_port: Int
  let @throttle_delay: Duration

  fn pub static new -> Scheduler {
    Scheduler {
      @redis_host = "localhost",
      @redis_port = 6379,
      @throttle_delay = Duration.from_secs(1)
    }
  }

  fn pub async check_throttle(url: String) -> Bool {
    let domain = extract_domain(url)

    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = fmt("*2\r\n$4\r\nHGET\r\n$17\r\nscheduler:throttle\r\n${domain.size}\r\n{domain}\r\n")
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    let response = String.from_bytes(buffer)
    client.close

    if response.starts_with?("$-1") {
      return true
    }

    let lines = response.split("\r\n")
    if lines.size > 1 {
      let timestamp_str = lines.get(1)
      let last_access = timestamp_str.to_int.unwrap_or(0)
      let now = Instant.now.to_unix_timestamp

      return (now - last_access) >= @throttle_delay.to_secs
    }

    true
  }

  fn pub async update_throttle(url: String) {
    let domain = extract_domain(url)
    let now = Instant.now.to_unix_timestamp
    let now_str = now.to_string

    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = fmt("*4\r\n$4\r\nHSET\r\n$17\r\nscheduler:throttle\r\n${domain.size}\r\n{domain}\r\n${now_str.size}\r\n{now_str}\r\n")
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn pub async schedule_recrawl(url: String, delay_secs: Int) {
    let next_crawl = Instant.now.to_unix_timestamp + delay_secs
    let next_crawl_str = next_crawl.to_string

    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = fmt("*4\r\n$4\r\nZADD\r\n$17\r\nscheduler:recrawl\r\n${next_crawl_str.size}\r\n{next_crawl_str}\r\n${url.size}\r\n{url}\r\n")
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn extract_domain(url: String) -> String {
    let protocol_end = url.index_of("://")

    let start = match protocol_end {
      case Some(idx) -> idx + 3
      case None -> 0
    }

    let after_protocol = url.slice(start, url.size)
    let slash_idx = after_protocol.index_of("/")

    match slash_idx {
      case Some(idx) -> after_protocol.slice(0, idx)
      case None -> after_protocol
    }
  }
}


