import std.string (String)
import std.net.http (Client, Method, Request, Response)
import std.option (Option)
import std.fmt (fmt)
import std.env

class pub async StorageClient {
  let @s3_endpoint: String
  let @s3_access_key: String
  let @s3_secret_key: String
  let @bucket: String
  let @client: Client

  fn pub static new -> StorageClient {
    StorageClient {
      @s3_endpoint = env.var("S3_ENDPOINT").unwrap_or("http://localhost:9000"),
      @s3_access_key = env.var("S3_ACCESS_KEY").unwrap_or("minioadmin"),
      @s3_secret_key = env.var("S3_SECRET_KEY").unwrap_or("minioadmin"),
      @bucket = "neural-search-crawled",
      @client = Client.new
    }
  }

  fn pub async store(doc: Document) {
    let key = generate_key(doc.url, doc.timestamp)
    let content = serialize_document(doc)

    let mut attempts = 0
    let max_attempts = 3

    loop {
      if attempts >= max_attempts {
        break
      }

      attempts = attempts + 1

      let url = fmt("{@s3_endpoint}/{@bucket}/{key}")
      let request = Request.new(method: Method.Put, url: url)

      request.header("Authorization", generate_auth_header())
      request.header("Content-Type", "application/json")
      request.body(content)

      let result = @client.execute(request).await

      match result {
        case Ok(response) -> {
          if response.status >= 200 and response.status < 300 {
            break
          } else if attempts < max_attempts {
            let backoff = Duration.from_millis(100 * (2.pow(attempts)))
            sleep(backoff)
          }
        }
        case Error(_) -> {
          if attempts < max_attempts {
            let backoff = Duration.from_millis(100 * (2.pow(attempts)))
            sleep(backoff)
          }
        }
      }
    }
  }

  fn generate_key(url: String, timestamp: Int) -> String {
    let domain = extract_domain(url)
    let path_hash = hash_string(url)

    fmt("{domain}/{timestamp}/{path_hash}.json")
  }

  fn serialize_document(doc: Document) -> String {
    let mut json = String.new

    json.push("{\"url\":\"")
    json.push(escape_json(doc.url))
    json.push("\",\"title\":\"")
    json.push(escape_json(doc.title))
    json.push("\",\"content\":\"")
    json.push(escape_json(doc.content))
    json.push("\",\"links\":[")

    doc.links.iter.each_with_index fn (link, i) {
      if i > 0 { json.push(",") }
      json.push("\"")
      json.push(escape_json(link))
      json.push("\"")
    }

    json.push("],\"lang\":\"")
    json.push(doc.lang)
    json.push("\",\"timestamp\":")
    json.push(doc.timestamp.to_string)
    json.push("}")

    json
  }

  fn escape_json(s: String) -> String {
    let mut result = String.new

    s.chars.each fn (c) {
      if c == '"' {
        result.push("\\\"")
      } else if c == '\\' {
        result.push("\\\\")
      } else if c == '\n' {
        result.push("\\n")
      } else if c == '\r' {
        result.push("\\r")
      } else if c == '\t' {
        result.push("\\t")
      } else {
        result.push(c)
      }
    }

    result
  }

  fn generate_auth_header -> String {
    fmt("AWS {@ s3_access_key}:{@s3_secret_key}")
  }

  fn extract_domain(url: String) -> String {
    let protocol_end = url.index_of("://")

    let start = match protocol_end {
      case Some(idx) -> idx + 3
      case None -> 0
    }

    let after_protocol = url.slice(start, url.size)
    let slash_idx = after_protocol.index_of("/")

    match slash_idx {
      case Some(idx) -> after_protocol.slice(0, idx)
      case None -> after_protocol
    }
  }

  fn hash_string(s: String) -> String {
    let mut hasher = Hasher.sha256
    hasher.write(s.to_byte_array)
    hasher.finish.to_hex_string.slice(0, 16)
  }
}


