import std.string (String)
import std.net.http (Client, Method, Request)
import std.option (Option)
import std.net.socket (TcpClient)

class pub async RobotsChecker {
  let @client: Client
  let @redis_host: String
  let @redis_port: Int

  fn pub static new -> RobotsChecker {
    RobotsChecker {
      @client = Client.new,
      @redis_host = "localhost",
      @redis_port = 6379
    }
  }

  fn pub async is_allowed(url: String) -> Bool {
    let domain = extract_domain(url)
    let path = extract_path(url)

    let cached_rules = get_cached_robots(domain).await

    let rules = match cached_rules {
      case Some(r) -> r
      case None -> {
        let fetched = fetch_robots(domain).await
        cache_robots(domain, fetched).await
        fetched
      }
    }

    check_rules(rules, path)
  }

  fn async fetch_robots(domain: String) -> String {
    let robots_url = "https://" + domain + "/robots.txt"
    let request = Request.new(method: Method.Get, url: robots_url)
    request.timeout(Duration.from_secs(10))

    let result = @client.execute(request).await

    match result {
      case Ok(response) -> {
        if response.status == 200 {
          response.body.to_string
        } else {
          ""
        }
      }
      case Error(_) -> ""
    }
  }

  fn async get_cached_robots(domain: String) -> Option[String] {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let cmd = "*2\r\n$3\r\nGET\r\n${domain.size + 7}\r\nrobots:{domain}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 8192).unwrap

    let response = String.from_bytes(buffer)
    client.close

    if response.starts_with?("$-1") {
      return Option.None
    }

    let lines = response.split("\r\n")
    if lines.size > 1 {
      Option.Some(lines.get(1))
    } else {
      Option.None
    }
  }

  fn async cache_robots(domain: String, rules: String) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let key = "robots:" + domain
    let ttl = 86400
    let cmd = "*4\r\n$5\r\nSETEX\r\n${key.size}\r\n{key}\r\n$5\r\n{ttl}\r\n${rules.size}\r\n{rules}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }

  fn check_rules(rules: String, path: String) -> Bool {
    let lines = rules.split("\n")
    let mut relevant = false
    let mut disallowed_paths = Array.new

    lines.iter.each fn (line) {
      let trimmed = line.trim

      if trimmed.starts_with?("User-agent:") {
        let agent = trimmed.slice(11, trimmed.size).trim
        relevant = agent == "*" or agent.contains?("NeuralSearchBot")
      } else if relevant and trimmed.starts_with?("Disallow:") {
        let disallow_path = trimmed.slice(9, trimmed.size).trim
        if disallow_path.size > 0 {
          disallowed_paths.push(disallow_path)
        }
      }
    }

    disallowed_paths.iter.any? fn (disallowed) {
      path.starts_with?(disallowed).not
    }
  }

  fn extract_domain(url: String) -> String {
    let protocol_end = url.index_of("://")

    let start = match protocol_end {
      case Some(idx) -> idx + 3
      case None -> 0
    }

    let after_protocol = url.slice(start, url.size)
    let slash_idx = after_protocol.index_of("/")

    match slash_idx {
      case Some(idx) -> after_protocol.slice(0, idx)
      case None -> after_protocol
    }
  }

  fn extract_path(url: String) -> String {
    let protocol_end = url.index_of("://")

    let start = match protocol_end {
      case Some(idx) -> idx + 3
      case None -> 0
    }

    let after_protocol = url.slice(start, url.size)
    let slash_idx = after_protocol.index_of("/")

    match slash_idx {
      case Some(idx) -> after_protocol.slice(idx, after_protocol.size)
      case None -> "/"
    }
  }
}


