class pub async Metrics {
  let @success: AtomicInt
  let @errors: AtomicInt
  let @duplicates: AtomicInt
  let @redis_host: String
  let @redis_port: Int

  fn pub static new -> Metrics {
    Metrics {
      @success = AtomicInt.new(0),
      @errors = AtomicInt.new(0),
      @duplicates = AtomicInt.new(0),
      @redis_host = "localhost",
      @redis_port = 6379
    }
  }

  fn pub async increment_success {
    let count = @success.fetch_add(1) + 1
    if count % 100 == 0 {
      publish_metric("success", count).await
    }
  }

  fn pub async increment_error {
    let count = @errors.fetch_add(1) + 1
    publish_metric("error", count).await
  }

  fn pub async increment_duplicate {
    let count = @duplicates.fetch_add(1) + 1
    if count % 50 == 0 {
      publish_metric("duplicate", count).await
    }
  }

  fn async publish_metric(metric_type: String, value: Int) {
    let client = TcpClient.new(ip: @redis_host, port: @redis_port).unwrap

    let value_str = value.to_string
    let cmd = "*3\r\n$4\r\nHSET\r\n$15\r\ncrawler:metrics\r\n${metric_type.size}\r\n{metric_type}\r\n${value_str.size}\r\n{value_str}\r\n"
    client.write_string(cmd).unwrap

    let mut buffer = ByteArray.new
    client.read(into: buffer, size: 256).unwrap

    client.close
  }
}


